package org.example.api.support;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;import org.example.config.ConfigManager;import java.io.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;
public final class SupportApiClient {private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();private final ObjectMapper json=new ObjectMapper().configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,false);private final String base;public SupportApiClient(){String b=ConfigManager.getDataApiBaseUrl();while(b.endsWith("/"))b=b.substring(0,b.length()-1);base=b;}
 public List<SavedView> savedViews(String screen,Integer uid){return get("/api/support/saved-views?screen="+enc(screen)+(uid==null?"":"&userId="+uid),new TypeReference<List<SavedView>>(){});}public void saveView(Integer uid,String screen,String name,String data){post("/api/support/saved-views",new SavedViewSave(uid,screen,name,data),Ok.class);}
 public List<PaymentRow> payments(String type,int id){return get("/api/support/payments?type="+enc(type)+"&id="+id,new TypeReference<List<PaymentRow>>(){});}public void recordPayment(PaymentRequest d){post("/api/support/payments",d,Ok.class);}
 public List<CommunicationRow> communications(){return get("/api/support/communications",new TypeReference<List<CommunicationRow>>(){});}public void communication(CommunicationRequest d){post("/api/support/communications",d,Ok.class);}public void markWhatsapp(String type,int id){postNoBody("/api/support/documents/"+enc(type)+"/"+id+"/whatsapp");}public void attachment(String type,int id,String path){put("/api/support/documents/"+enc(type)+"/"+id+"/attachment",new Text(path),Ok.class);}public void notes(String type,int id,String notes){put("/api/support/documents/"+enc(type)+"/"+id+"/notes",new Text(notes),Ok.class);}public void activity(String type,int id,String action,String detail,String user){postNoBody("/api/support/activity?type="+enc(type)+"&id="+id+"&action="+enc(action)+"&detail="+enc(detail)+"&user="+enc(user));}public String returnPartyEmail(String no){return get("/api/support/returns/"+enc(no)+"/party-email",Text.class).value();}public String duplicateSale(int id,String user){return post("/api/support/sales/"+id+"/duplicate?user="+enc(user),null,Text.class).value();}public void cancelPurchase(int id){postNoBody("/api/support/purchases/"+id+"/cancel");}
 public List<SearchRow> search(String q){return get("/api/support/search?q="+enc(q),new TypeReference<List<SearchRow>>(){});}public ReportSummary businessReport(String from,String to){return get("/api/support/business-report?from="+enc(from)+"&to="+enc(to),ReportSummary.class);}public String setting(String k,String d){return get("/api/support/settings/"+enc(k)+"?def="+enc(d),Text.class).value();}public void setSetting(String k,String v){put("/api/support/settings/"+enc(k),new Text(v),Ok.class);}public void ensureBackup(){postNoBody("/api/support/backup/ensure");}public void ensureApplicationMetadata(String appId,int schemaVersion,String appVersion){postNoBody("/api/support/backup/application-metadata?appId="+enc(appId)+"&schemaVersion="+schemaVersion+"&appVersion="+enc(appVersion));}public BackupMeta backupMeta(String f){return getNullable("/api/support/backup/meta?file="+enc(f),BackupMeta.class);}public void backupMeta(BackupMeta d){put("/api/support/backup/meta",d,Ok.class);}public void legacyConstraints(boolean add){postNoBody("/api/support/backup/legacy-constraints?add="+add);}
 private <T>T get(String p,Class<T>c){return req("GET",p,null,c,null,false);}private <T>T getNullable(String p,Class<T>c){return req("GET",p,null,c,null,true);}private <T>T get(String p,TypeReference<T>t){return req("GET",p,null,null,t,false);}private <T>T post(String p,Object b,Class<T>c){return req("POST",p,b,c,null,false);}private <T>T put(String p,Object b,Class<T>c){return req("PUT",p,b,c,null,false);}private void postNoBody(String p){req("POST",p,null,Ok.class,null,false);}private <T>T req(String m,String p,Object body,Class<T>c,TypeReference<T>t,boolean nullable){try{HttpRequest.Builder b=HttpRequest.newBuilder(URI.create(base+p)).timeout(Duration.ofSeconds(30)).header("Accept","application/json");org.example.api.ApiSession.authorize(b);if(body!=null)b.header("Content-Type","application/json").method(m,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));else b.method(m,HttpRequest.BodyPublishers.noBody());var r=http.send(b.build(),HttpResponse.BodyHandlers.ofString());if(nullable&&r.statusCode()==204)return null;if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("Support API error ("+r.statusCode()+"): "+r.body());if(nullable&&(r.body()==null||r.body().isBlank()||"null".equals(r.body())))return null;return t!=null?json.readValue(r.body(),t):json.readValue(r.body(),c);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}catch(IOException e){throw new IllegalStateException("Cannot reach support API at "+base,e);}}
 private String enc(String v){return URLEncoder.encode(v==null?"":v,StandardCharsets.UTF_8);}public record SavedView(String name,String data){}public record SavedViewSave(Integer userId,String screen,String name,String data){}public record PaymentRow(int id,String date,String reference,String mode,double amount,String notes,String receivedFrom,String attachment){}public record PaymentRequest(String documentType,int documentId,String date,double amount,String mode,String reference,String notes,String receivedFrom,String paymentType,String attachment,String createdBy){}public record CommunicationRow(int id,String entityType,int entityId,String documentLabel,String channel,String recipient,String subject,String status,String errorMessage,String createdBy,String createdAt){}public record CommunicationRequest(String entityType,int entityId,String channel,String recipient,String subject,String status,String errorMessage,String createdBy){}public record SearchRow(String module,String reference,String description,String detail,String targetFxml){}public record ReportSummary(double salesTotal,double purchaseTotal,double stockValue,List<List<String>> salesByCustomer,List<List<String>> purchasesBySupplier,List<List<String>> lowStock){}public record Text(String value){}public record BackupMeta(String fileName,String source,String integrityStatus,Integer schemaVersion,String applicationId,long fileSize){}public record Ok(boolean success,String message){}
}
